import React, { useId } from 'react';
import { getTextareaIds, getTextareaAriaProps } from '../lib/core';
import type { TextareaBaseProps } from '../lib/core';
import styles from './textarea.module.scss';

export interface TextareaProps extends React.TextareaHTMLAttributes<HTMLTextAreaElement>, TextareaBaseProps {}

const Textarea = React.forwardRef<HTMLTextAreaElement, TextareaProps>(({ className = '', label, error, helperText, required, id: providedId, ...props }, ref) => {
	const generatedId = useId();
	const id = providedId || generatedId;
	const ids = getTextareaIds(id);
	const ariaProps = getTextareaAriaProps(ids, error, helperText);

	return (
		<div className={styles.textareaWrapper}>
			{label && (
				<label htmlFor={id} className={`${styles.label} ${required ? styles.required : ''}`}>
					{label}
				</label>
			)}
			<textarea ref={ref} id={id} className={`${styles.textarea} ${error ? styles.error : ''} ${className}`} {...ariaProps} {...props} />
			{error && (
				<span id={ids.error} className={styles.errorText}>
					{error}
				</span>
			)}
			{!error && helperText && (
				<span id={ids.helper} className={styles.helperText}>
					{helperText}
				</span>
			)}
		</div>
	);
});

Textarea.displayName = 'Textarea';

export { Textarea };
export default Textarea;

@use '../../../styles/variables/colors' as *;

.textareaWrapper {
	display: flex;
	flex-direction: column;
	gap: var(--tile-textarea-label-gap, #{$spacing-1});
	width: 100%;
}

.textarea {
	display: flex;
	min-height: var(--tile-textarea-min-height, 5rem);
	width: 100%;
	border-radius: var(--tile-textarea-radius, #{$radius});
	border: var(--tile-textarea-border-width, 1px) solid var(--tile-textarea-border, #{$border});
	background-color: var(--tile-textarea-background, #{$background});
	padding: var(--tile-textarea-padding, #{$spacing-3} #{$spacing-3});
	font-size: var(--tile-textarea-font-size, #{$text-sm});
	box-shadow: var(--tile-textarea-shadow, none);
	color: $foreground;
	transition: all $transition-fast;
	outline: none;
	resize: vertical;
	font-family: inherit;
	line-height: var(--tile-textarea-line-height, #{$leading-normal});

	&::placeholder {
		color: var(--tile-textarea-placeholder, #{$muted-foreground});
	}

	&:focus {
		outline: none;
		border-color: var(--tile-textarea-focus-border, #{$ring});
		box-shadow: var(--tile-textarea-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
	}

	&:disabled,
	&.disabled {
		pointer-events: none;
		opacity: var(--tile-textarea-disabled-opacity, 0.5);
		cursor: not-allowed;
		background-color: var(--tile-textarea-disabled-background, #{$field-disabled});
		color: var(--tile-textarea-disabled-color, #{$foreground});
	}

	&.error {
		border-color: $destructive;
		box-shadow: var(--tile-textarea-error-shadow, none);

		&:focus {
			border-color: $destructive;
			box-shadow: var(--tile-textarea-error-focus-shadow, 0 0 0 1px #{$destructive});
		}
	}
}

.label {
	display: block;
	font-size: var(--tile-textarea-label-font-size, #{$text-sm});
	font-weight: $font-medium;
	color: $foreground;
	line-height: $leading-normal;

	&.required::after {
		content: ' *';
		color: $destructive;
	}
}

.helperText {
	font-size: var(--tile-textarea-description-font-size, #{$text-xs});
	color: var(--tile-textarea-description-color, #{$muted-foreground});
	line-height: var(--tile-textarea-description-line-height, #{$leading-normal});
}

.errorText {
	font-size: var(--tile-textarea-description-font-size, #{$text-xs});
	color: $destructive;
	line-height: var(--tile-textarea-description-line-height, #{$leading-normal});
}
